export function autoCalcAvailableBudget(current, previous) {
    var approved = parseFloat(current.getValue('approved')) || 0;
    var committed = parseFloat(current.getValue('committed')) || 0;
    var spent = parseFloat(current.getValue('spent')) || 0;
    var available = approved - committed - spent;
    if (available < 0) {
        available = 0;
    }
    current.setValue('available', available);
}
export function setPlanDefaults(current, previous) {
    if (!current.getValue('status')) {
        current.setValue('status', 'draft');
    }
    if (!current.getValue('version') || current.getValue('version') == '0') {
        current.setValue('version', 1);
    }
}
